<section class="section"><h1>Users</h1><table class="data-table"><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach ($listing['items'] as $user): ?><tr><td><strong><?= e($user['display_name'] ?? $user['username']) ?></strong><br><span class="muted">@<?= e($user['username']) ?></span></td><td><span class="badge badge-role"><?= e($user['role']) ?></span></td><td><?= empty($user['deleted_at']) ? 'Active' : 'Suspended' ?></td><td><form action="/admin/users/<?= e($user['id']) ?>/role" method="post" class="inline-form"><?= \App\Util\Csrf::field() ?><select name="role"><option value="user">User</option><option value="editor" <?= $user['role'] === 'editor' ? 'selected' : '' ?>>Editor</option><option value="admin" <?= $user['role'] === 'admin' ? 'selected' : '' ?>>Admin</option></select><button class="button small" type="submit">Save</button></form><form action="/admin/users/<?= e($user['id']) ?>/suspend" method="post" class="inline-form"><?= \App\Util\Csrf::field() ?><button class="button button-danger small" type="submit">Suspend</button></form></td></tr><?php endforeach; ?></tbody></table></section>
